const express = require('express');
const { Worker } = require('worker_threads');
const path = require('path');
const { checkUserToken } = require('../auth');
const { db } = require('../db');

const app = express();

app.post('/api/lending/applications/:appId/score', checkUserToken, async (req, res) => {
  const appRecord = await db.query(
    'SELECT id FROM loan_applications WHERE id = $1 AND applicant_id = $2',
    [req.params.appId, req.user.id]
  );
  if (!appRecord.rows.length) {
    return res.status(403).json({ error: 'Forbidden: application does not belong to current user' });
  }

  const worker = new Worker(path.resolve(__dirname, '../workers/riskScoreWorker.js'), {
    workerData: { applicationId: req.params.appId }
  });

  worker.on('message', (scoreData) => {
    res.json({ applicationId: req.params.appId, riskTier: scoreData.tier, score: scoreData.score });
  });
});
